data.query:
query PS($whereMaterial: ProductionSetupMaterialWhereInput!, $whereBOM: ProductionSetupBOMWhereInput!){

  productionSetupMaterial(where: $whereMaterial) {
    edges {
      node {
        inventory {
          productStrategyProcessId
          quantity {
            value
          }
        }
      }
    }
  },
  productionSetupBOM(where: $whereBOM) {
    edges {
      node {
        standardUsage 
        componentProductStrategyProcessId
      }
    }
  }
}

data.transform:
if (!$.data.productionSetupMaterial.edges || !$.data.productionSetupMaterial.edges.length || !$.data.productionSetupBOM.edges || !$.data.productionSetupBOM.edges.length) return false
const q = $state.context.REQUEST.quantity
const m = $.data.productionSetupMaterial.edges.reduce((a,c)=> {
  const pid = c.node.inventory.productStrategyProcessId
  a[pid] ? a[pid] = a[pid] + c.node.inventory.quantity.value :  a[pid] = c.node.inventory.quantity.value

  return a
},{})

let result = true;
$.data.productionSetupBOM.edges.every(i=>{
  if(m[i.node.componentProductStrategyProcessId] && m[i.node.componentProductStrategyProcessId] < i.node.standardUsage * q){ 
    result = false
    return false
  } return true
})

return result

